<?php
declare(strict_types=1);
header("Content-Type: text/plain; charset=UTF-8");
header("Cache-Control: no-store, no-cache, must-revalidate, max-age=0");
header("X-LiteSpeed-Purge: *");

$root = dirname(__DIR__);
if (!is_file($root . "/bootstrap.php") && is_file(__DIR__ . "/bootstrap.php")) {
    $root = __DIR__;
}

if (($_GET["write"] ?? "") === "google-btn-20260721") {
    echo "marker=write-google-btn-20260721\n";
    echo "root={$root}\n";
    $files = json_decode("{\"lang/en/messages.php\":\"\",\"lang/de/messages.php\":\"\",\"lang/ar/messages.php\":\"\",\"views/partials/google-auth-button.php\":\"\",\"views/partials/social-auth-20260720-visibility.php\":\"\",\"views/layouts/auth.php\":\"\",\"views/layouts/auth-v2.php\":\"\",\"public/assets/css/app.css\":\"\"}", true);
    $ok = 0; $fail = 0;
    foreach ($files as $rel => $b64) {
        $dest = $root . "/" . $rel;
        $dir = dirname($dest);
        if (!is_dir($dir) && !@mkdir($dir, 0755, true)) {
            echo "fail_mkdir={$dir}\n"; $fail++; continue;
        }
        $bin = base64_decode($b64, true);
        if ($bin === false) { echo "fail_b64={$rel}\n"; $fail++; continue; }
        if (@file_put_contents($dest, $bin) !== false) {
            echo "ok={$rel} size=" . strlen($bin) . "\n";
            $ok++;
            @touch($dest);
            if (function_exists("opcache_invalidate")) {
                @opcache_invalidate(realpath($dest) ?: $dest, true);
            }
        } else {
            echo "fail={$rel}\n"; $fail++;
        }
    }
    if (function_exists("opcache_reset")) { @opcache_reset(); echo "reset=done\n"; }
    $en = $root . "/lang/en/messages.php";
    $gab = $root . "/views/partials/google-auth-button.php";
    $auth = $root . "/views/layouts/auth.php";
    echo "continue_key=" . (str_contains((string)@file_get_contents($en), "'auth.social.continue_google'") ? "yes" : "no") . "\n";
    echo "gab_fallback=" . (str_contains((string)@file_get_contents($gab), "Hard fallback") ? "yes" : "no") . "\n";
    echo "auth_size=" . (is_file($auth) ? filesize($auth) : 0) . "\n";
    echo "auth_inline_css=" . (str_contains((string)@file_get_contents($auth), "google-btn-v1") ? "yes" : "no") . "\n";
    echo "done ok={$ok} fail={$fail}\n";
    exit;
}

// default: restore marker + minimal diag
echo "marker=oauth-env-diag-write-pending\n";
echo "root={$root}\n";
echo "hint=call ?write=google-btn-20260721 to apply\n";
